//! Player names and other short texts from phones, cleaned like
//! `@tvpipe/party`'s `names.ts` (docs/multiscreen-design.md §1.6): NFC,
//! whitespace collapsed, invisible and control characters removed, at
//! most N user-perceived characters; and the key two names are compared
//! by (NFKD, marks removed, lowercase, no whitespace).
//!
//! The Unicode data comes from `tables.rs` (generated by
//! `scripts/vectors/party_unicode_tables.py`); grapheme clusters follow
//! the parts of UAX #29 a name needs (marks, ZWJ emoji sequences, flags,
//! Hangul). `tests/vectors/names.txt` holds Node's answers.

mod tables;

use tables::{COMBINING, COMPOSITIONS, DECOMPOSITIONS, MARKS};

/// The longest name, in user-perceived characters.
pub(crate) const MAX_NAME: usize = 16;

/// JavaScript's `\s` (and what `String.prototype.trim` removes).
pub(crate) fn is_js_space(c: char) -> bool {
    matches!(
        c,
        '\t' | '\n' | '\u{0b}' | '\u{0c}' | '\r' | ' ' | '\u{a0}' | '\u{1680}' | '\u{2000}'
            ..='\u{200a}'
                | '\u{2028}'
                | '\u{2029}'
                | '\u{202f}'
                | '\u{205f}'
                | '\u{3000}'
                | '\u{feff}'
    )
}

/// Control characters (C0, C1), bidi overrides and isolates, zero-width
/// characters other than ZWJ (emoji sequences need it), the BOM, line and
/// paragraph separators, and private-use characters.
fn is_stripped(c: char) -> bool {
    matches!(
        c,
        '\u{0}'..='\u{1f}'
            | '\u{7f}'..='\u{9f}'
            | '\u{200b}' | '\u{200c}' | '\u{200e}' | '\u{200f}'
            | '\u{202a}'..='\u{202e}'
            | '\u{2066}'..='\u{2069}'
            | '\u{feff}' | '\u{2028}' | '\u{2029}'
            | '\u{e000}'..='\u{f8ff}'
    )
}

fn js_trim(s: &str) -> &str {
    s.trim_matches(is_js_space)
}

/// Untrusted text cleaned up for display: NFC, invisible and control
/// characters removed, whitespace runs collapsed to one space, trimmed,
/// at most `max` user-perceived characters. Not an HTML escape: render
/// it as text.
pub(crate) fn clean_text(input: &str, max: usize) -> String {
    let nfc = nfc(input);
    let mut s = String::with_capacity(nfc.len());
    let mut in_space = false;
    for c in nfc.chars() {
        if is_js_space(c) {
            if !in_space {
                s.push(' ');
            }
            in_space = true;
        } else {
            s.push(c);
            in_space = false;
        }
    }
    let s: String = s.chars().filter(|&c| !is_stripped(c)).collect();
    let mut collapsed = String::with_capacity(s.len());
    for c in s.chars() {
        if c == ' ' && collapsed.ends_with(' ') {
            continue;
        }
        collapsed.push(c);
    }
    let trimmed = js_trim(&collapsed);
    js_trim(truncate_graphemes(trimmed, max)).to_owned()
}

/// How names compare for uniqueness: case- and accent-insensitive.
pub(crate) fn name_key(name: &str) -> String {
    let stripped: String = nfkd(name).chars().filter(|&c| !is_mark(c)).collect();
    stripped
        .to_lowercase()
        .chars()
        .filter(|&c| !is_js_space(c))
        .collect()
}

// ---------------------------------------------------------------------------
// Normalization

const S_BASE: u32 = 0xac00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11a7;
const L_COUNT: u32 = 19;
const V_COUNT: u32 = 21;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = V_COUNT * T_COUNT;
const S_COUNT: u32 = L_COUNT * N_COUNT;

fn decompose_into(c: char, compat: bool, out: &mut Vec<char>) {
    let cp = c as u32;
    if (S_BASE..S_BASE + S_COUNT).contains(&cp) {
        let s = cp - S_BASE;
        let push = |out: &mut Vec<char>, v: u32| out.extend(char::from_u32(v));
        push(out, L_BASE + s / N_COUNT);
        push(out, V_BASE + (s % N_COUNT) / T_COUNT);
        if s % T_COUNT != 0 {
            push(out, T_BASE + s % T_COUNT);
        }
        return;
    }
    match DECOMPOSITIONS.binary_search_by_key(&c, |&(k, _, _)| k) {
        Ok(i) => {
            let (_, nfd, nfkd) = DECOMPOSITIONS[i];
            let d = if compat {
                nfkd
            } else if nfd.is_empty() {
                // Only a compatibility decomposition.
                ""
            } else {
                nfd
            };
            if d.is_empty() {
                out.push(c);
            } else {
                out.extend(d.chars());
            }
        }
        Err(_) => out.push(c),
    }
}

fn combining_class(c: char) -> u8 {
    let cp = c as u32;
    match COMBINING.binary_search_by(|&(lo, hi, _)| {
        if hi < cp {
            std::cmp::Ordering::Less
        } else if lo > cp {
            std::cmp::Ordering::Greater
        } else {
            std::cmp::Ordering::Equal
        }
    }) {
        Ok(i) => COMBINING[i].2,
        Err(_) => 0,
    }
}

fn in_ranges(table: &[(u32, u32)], cp: u32) -> bool {
    table
        .binary_search_by(|&(lo, hi)| {
            if hi < cp {
                std::cmp::Ordering::Less
            } else if lo > cp {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

fn is_mark(c: char) -> bool {
    in_ranges(&MARKS, c as u32)
}

/// Full decomposition with the canonical ordering of combining marks.
fn decompose(s: &str, compat: bool) -> Vec<char> {
    let mut out = Vec::with_capacity(s.len());
    for c in s.chars() {
        decompose_into(c, compat, &mut out);
    }
    // Canonical ordering: a stable sort of each run of non-starters.
    let mut i = 0;
    while i < out.len() {
        if combining_class(out[i]) == 0 {
            i += 1;
            continue;
        }
        let start = i;
        while i < out.len() && combining_class(out[i]) != 0 {
            i += 1;
        }
        out[start..i].sort_by_key(|&c| combining_class(c));
    }
    out
}

fn compose_pair(a: char, b: char) -> Option<char> {
    let (ap, bp) = (a as u32, b as u32);
    if (L_BASE..L_BASE + L_COUNT).contains(&ap) && (V_BASE..V_BASE + V_COUNT).contains(&bp) {
        return char::from_u32(S_BASE + ((ap - L_BASE) * V_COUNT + (bp - V_BASE)) * T_COUNT);
    }
    if (S_BASE..S_BASE + S_COUNT).contains(&ap)
        && (ap - S_BASE) % T_COUNT == 0
        && (T_BASE + 1..T_BASE + T_COUNT).contains(&bp)
    {
        return char::from_u32(ap + (bp - T_BASE));
    }
    COMPOSITIONS
        .binary_search_by(|&(x, y, _)| (x, y).cmp(&(a, b)))
        .ok()
        .map(|i| COMPOSITIONS[i].2)
}

/// Normalization Form C.
pub(crate) fn nfc(s: &str) -> String {
    if s.is_ascii() {
        return s.to_owned();
    }
    let d = decompose(s, false);
    let mut out: Vec<char> = Vec::with_capacity(d.len());
    let mut starter: Option<usize> = None;
    // The class of the last character after the starter (`None`: the
    // starter is the last character).
    let mut last_class: Option<u8> = None;
    for c in d {
        let class = combining_class(c);
        if let Some(si) = starter {
            let blocked = matches!(last_class, Some(lc) if lc == 0 || lc >= class);
            if !blocked {
                if let Some(composite) = compose_pair(out[si], c) {
                    out[si] = composite;
                    continue;
                }
            }
        }
        if class == 0 {
            starter = Some(out.len());
            last_class = None;
        } else {
            last_class = Some(class);
        }
        out.push(c);
    }
    out.into_iter().collect()
}

/// Normalization Form KD (compatibility decompositions for the scripts in
/// the tables, canonical ones for everything).
pub(crate) fn nfkd(s: &str) -> String {
    decompose(s, true).into_iter().collect()
}

// ---------------------------------------------------------------------------
// Grapheme clusters

#[derive(Clone, Copy, PartialEq, Eq)]
enum Gcb {
    Cr,
    Lf,
    Extend,
    Zwj,
    RegionalIndicator,
    L,
    V,
    T,
    Lv,
    Lvt,
    Other,
}

fn gcb(c: char) -> Gcb {
    let cp = c as u32;
    match cp {
        0x0d => Gcb::Cr,
        0x0a => Gcb::Lf,
        0x200d => Gcb::Zwj,
        0x200c | 0x1f3fb..=0x1f3ff | 0xe0020..=0xe007f | 0xff9e..=0xff9f => Gcb::Extend,
        0x1f1e6..=0x1f1ff => Gcb::RegionalIndicator,
        0x1100..=0x115f | 0xa960..=0xa97c => Gcb::L,
        0x1160..=0x11a7 | 0xd7b0..=0xd7c6 => Gcb::V,
        0x11a8..=0x11ff | 0xd7cb..=0xd7fb => Gcb::T,
        0xac00..=0xd7a3 if (cp - S_BASE) % T_COUNT == 0 => Gcb::Lv,
        0xac00..=0xd7a3 => Gcb::Lvt,
        _ if is_mark(c) => Gcb::Extend,
        _ => Gcb::Other,
    }
}

