fn is_pictographic(c: char) -> bool {
    in_ranges(&EXTENDED_PICTOGRAPHIC, c as u32)
}

/// The byte offsets where user-perceived characters start (UAX #29's
/// extended grapheme clusters, without Prepend and SpacingMark details).
fn grapheme_starts(s: &str) -> Vec<usize> {
    let mut starts = Vec::new();
    let mut prev: Option<(Gcb, bool)> = None;
    // Regional indicators in a row before this character.
    let mut ri_run = 0usize;
    // ExtPict Extend* seen (GB11), and whether a ZWJ followed it.
    let mut pict = false;
    let mut pict_zwj = false;
    for (i, c) in s.char_indices() {
        let class = gcb(c);
        let picto = is_pictographic(c);
        let joined = match prev {
            None => false,
            Some((p, _)) => match (p, class) {
                (Gcb::Cr, Gcb::Lf) => true,
                (Gcb::Cr | Gcb::Lf, _) | (_, Gcb::Cr | Gcb::Lf) => false,
                (Gcb::L, Gcb::L | Gcb::V | Gcb::Lv | Gcb::Lvt) => true,
                (Gcb::Lv | Gcb::V, Gcb::V | Gcb::T) => true,
                (Gcb::Lvt | Gcb::T, Gcb::T) => true,
                (_, Gcb::Extend | Gcb::Zwj) => true,
                (Gcb::Zwj, _) if picto && pict_zwj => true,
                (Gcb::RegionalIndicator, Gcb::RegionalIndicator) => ri_run % 2 == 1,
                _ => false,
            },
        };
        if !joined {
            starts.push(i);
        }
        // GB11 state.
        if picto {
            pict = true;
            pict_zwj = false;
        } else if class == Gcb::Extend && pict {
            pict_zwj = false;
        } else if class == Gcb::Zwj && pict {
            pict_zwj = true;
            pict = false;
        } else {
            pict = false;
            pict_zwj = false;
        }
        ri_run = if class == Gcb::RegionalIndicator {
            ri_run + 1
        } else {
            0
        };
        prev = Some((class, picto));
    }
    starts
}

/// Number of user-perceived characters.
#[cfg(test)]
pub(crate) fn graphemes(s: &str) -> usize {
    grapheme_starts(s).len()
}

/// The first `max` user-perceived characters.
pub(crate) fn truncate_graphemes(s: &str, max: usize) -> &str {
    match grapheme_starts(s).get(max) {
        Some(&end) => &s[..end],
        None => s,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::testutil::vectors;
    use crate::value::Value;

    fn string(json: &str) -> String {
        match Value::parse(json).unwrap() {
            Value::String(s) => s,
            v => panic!("not a string: {v}"),
        }
    }

    #[test]
    fn vectors_from_node() {
        for b in vectors("names.txt") {
            let name = b.str("name");
            let input = string(b.str("input"));
            let clean = clean_text(&input, MAX_NAME);
            assert_eq!(clean, string(b.str("clean")), "{name}");
            assert_eq!(name_key(&clean), string(b.str("key")), "{name} (key)");
        }
    }

    #[test]
    fn normalization() {
        assert_eq!(nfc("e\u{301}"), "\u{e9}");
        assert_eq!(nfc("\u{1100}\u{1161}\u{11a8}"), "\u{ac01}");
        assert_eq!(nfkd("\u{ac01}"), "\u{1100}\u{1161}\u{11a8}");
        // Canonical ordering: dot below (220) before acute (230).
        assert_eq!(nfc("q\u{301}\u{323}"), "q\u{323}\u{301}");
        assert_eq!(nfc("a\u{323}\u{302}"), "\u{1ead}");
        assert_eq!(nfkd("\u{fb01}"), "fi");
        assert_eq!(graphemes("👩‍👩‍👧‍👦"), 1);
        assert_eq!(graphemes("🇦🇹🇩🇪x"), 3);
        assert_eq!(graphemes("e\u{301}\r\n"), 2);
        assert_eq!(truncate_graphemes("👍🏽abc", 2), "👍🏽a");
    }

    #[test]
    fn hostile_input_does_not_panic() {
        let mut s = String::new();
        for cp in (0..0x110000u32).step_by(97) {
            if let Some(c) = char::from_u32(cp) {
                s.push(c);
            }
        }
        let _ = clean_text(&s, MAX_NAME);
        let _ = name_key(&s);
        let marks: String = std::iter::repeat_n('\u{301}', 10_000).collect();
        assert_eq!(clean_text(&marks, MAX_NAME), nfc(&marks));
    }
}
